// Split-Ansicht für Login, Registrierung und Passwort: links Formular, rechts Navy-Fläche
// mit Nutzenversprechen. Wird innerhalb des normalen Seitenkopfs/-fußes gerendert.

import { BadgeCheck, Check, Clock, FileLock2, MessagesSquare } from "lucide-react";
import { PROVISION } from "@/lib/invest/markt";
import { ROLLEN } from "@/lib/plattform/konstanten";

const NUTZEN = {
  flaeche: ["Kostenlose Vorprüfung Ihrer Fläche", "Pachtangebot direkt im Portal", "Status von der Prüfung bis zum Betrieb"],
  landwirt: ["Agri-PV: verpachten, selbst investieren oder beteiligen", "Landwirtschaft bleibt Hauptnutzung", "Ein fester Ansprechpartner"],
  investor: ["Suchprofil mit Matching-Score", "NDA per Klick, Datenraum im Portal", PROVISION.kaeufer.text.charAt(0).toUpperCase() + PROVISION.kaeufer.text.slice(1)],
  anbieter: ["Anonymer Teaser, Datenraum nach NDA", "Aufrufe, Merker und NDA-Anfragen live", `Provision ${PROVISION.verkaeufer.text}`],
  unternehmen: ["Reststrom-Pool, Solarcarport, Speicher", "Angebote und Unterlagen an einem Ort", "Status jederzeit einsehbar"],
  mitglied: ["Genossenschaft und Energiegemeinschaften", "Beteiligung und Status einsehen", "Nachrichten an einem Ort"],
  kommune: ["Projekte im Gemeindegebiet ab Planung", "Beteiligungsmodelle und § 6 EEG im Überblick", "Fester Ansprechpartner für Verwaltung und Gemeinderat"],
};

export default function AuthRahmen({ eyebrow, titel, text, rolle, children }) {
  const r = ROLLEN.find((x) => x.id === rolle);
  const punkte = NUTZEN[rolle] || [
    "Status aller Anfragen, Flächen und Projekte",
    "Dokumente und Nachrichten sicher an einem Ort",
    "Für Flächeneigentümer und Investoren kostenfrei",
  ];
  return (
    <section className="relative overflow-hidden bg-sand-50">
      <div aria-hidden="true" className="ov-grid-bg-light pointer-events-none absolute inset-0" />
      <div className="ov-container relative grid gap-8 py-10 md:py-16 lg:grid-cols-[minmax(0,1.05fr)_minmax(0,0.95fr)] lg:gap-12">
        <div className="min-w-0 rounded-[2rem] bg-white p-6 shadow-[0_30px_80px_-50px_rgba(3,18,43,0.45)] ring-1 ring-ink-200/70 sm:p-8 md:p-10">
          {eyebrow && <p className="text-[12.5px] font-semibold uppercase tracking-[0.16em] text-ov-700">{eyebrow}</p>}
          <h1 className="mt-2 font-display text-[28px] font-extrabold leading-tight tracking-tight text-ink-900 md:text-[34px]">{titel}</h1>
          {text && <p className="mt-3 text-[15.5px] leading-relaxed text-ink-600">{text}</p>}
          <div className="mt-8">{children}</div>
        </div>

        <aside className="ov-noise relative min-w-0 overflow-hidden rounded-[2rem] bg-navy-950 p-7 text-white sm:p-10 lg:sticky lg:top-28 lg:self-start lg:p-12">
          <div aria-hidden="true" className="ov-grid-bg absolute inset-0" />
          <div aria-hidden="true" className="absolute -right-24 -top-24 h-80 w-80 rounded-full bg-ov-500/35 blur-[110px]" />
          <div aria-hidden="true" className="absolute -bottom-32 -left-10 h-72 w-72 rounded-full bg-navy-400/25 blur-[110px]" />
          <div className="relative flex h-full flex-col">
            <p className="text-[12.5px] font-semibold uppercase tracking-[0.16em] text-ov-300">{r ? `Portal für ${r.label}` : "Ein Login für alles"}</p>
            <p className="mt-4 font-display text-[26px] font-extrabold leading-tight tracking-tight md:text-[32px]">
              Flächen. Projekte. Kapital. Strom. <span className="text-ov-300">An einem Ort.</span>
            </p>
            <ul className="mt-8 space-y-4">
              {punkte.map((p) => (
                <li key={p} className="flex items-start gap-3 text-[15.5px] leading-relaxed text-white/85">
                  <span className="mt-0.5 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-ov-500/20 text-ov-300">
                    <Check aria-hidden="true" className="h-3.5 w-3.5" strokeWidth={3} />
                  </span>
                  <span className="min-w-0">{p}</span>
                </li>
              ))}
            </ul>
            <div className="mt-10 grid gap-3 sm:grid-cols-3 lg:mt-auto lg:pt-10">
              {[
                { icon: BadgeCheck, t: "ÖKOVOLT Gruppe", s: "seit 2010" },
                { icon: FileLock2, t: "Vertraulich", s: "Datenraum nach NDA" },
                { icon: MessagesSquare, t: "Direkter Draht", s: "Nachrichten im Portal" },
              ].map((k) => {
                const Icon = k.icon;
                return (
                  <div key={k.t} className="ov-glass rounded-2xl p-4">
                    <Icon aria-hidden="true" className="h-5 w-5 text-ov-300" />
                    <p className="mt-2 text-[14px] font-semibold">{k.t}</p>
                    <p className="text-[12.5px] text-white/60">{k.s}</p>
                  </div>
                );
              })}
            </div>
            <p className="mt-6 flex items-center gap-2 text-[12.5px] text-white/50">
              <Clock aria-hidden="true" className="h-3.5 w-3.5" /> Antwort in der Regel innerhalb von zwei Werktagen
            </p>
          </div>
        </aside>
      </div>
    </section>
  );
}
"use client";

// Anmeldung: Passwort oder passwortlos per E-Mail-Link; bei aktiver Zwei-Faktor-Anmeldung folgt der Code-Schritt.

import { useId, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Eye, EyeOff, KeyRound, Loader2, LogIn, MailCheck, Wand2 } from "lucide-react";
import { senden, sicheresZiel } from "@/lib/plattform/client";
import { eingabe, Feld, FehlerBox, ErfolgBox } from "@/components/Portal/felder";
import { cn } from "@/components/ui/cn";
import ZweiFaktorSchritt from "./ZweiFaktorSchritt";

const HINWEISE = {
  abgemeldet: { ton: "ok", text: "Sie wurden abgemeldet." },
  "link-ungueltig": { ton: "fehler", text: "Der Link ist ungültig oder abgelaufen. Melden Sie sich an oder fordern Sie einen neuen Link an." },
  "passwort-gesetzt": { ton: "ok", text: "Ihr neues Passwort ist gespeichert." },
  "konto-geloescht": { ton: "ok", text: "Ihr Konto wurde gelöscht. Vielen Dank für Ihr Vertrauen." },
  "zwei-faktor-abgelaufen": { ton: "fehler", text: "Die Anmeldung ist abgelaufen. Bitte melden Sie sich erneut an." },
};

const knopf =
  "inline-flex h-12 w-full items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] transition-colors hover:bg-ov-700 disabled:opacity-60";

/** Nach erfolgreicher Anmeldung weiterleiten */
export function weiterNachLogin(router, weiter, nutzer) {
  const standard = nutzer?.zweiFaktorPflichtOffen ? "/portal/sicherheit?pflicht=1" : nutzer?.rollen?.includes("admin") ? "/portal/admin" : "/portal";
  router.replace(nutzer?.zweiFaktorPflichtOffen ? standard : sicheresZiel(weiter, standard));
  router.refresh();
}

export default function LoginFormular({ weiter, hinweis, demoKonten = [], demo = false }) {
  const router = useRouter();
  const id = useId();
  const [modus, setModus] = useState("passwort"); // passwort | link | link-gesendet | zwei-faktor
  const [email, setEmail] = useState("");
  const [passwort, setPasswort] = useState("");
  const [zeigen, setZeigen] = useState(false);
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const [meldung, setMeldung] = useState(HINWEISE[hinweis] || null);

  async function anmelden(e) {
    e.preventDefault();
    setLaeuft(true);
    setFehler("");
    try {
      const r = await senden("/api/auth/login", { body: { email, passwort } });
      if (r.zweiFaktor) {
        setModus("zwei-faktor");
        setLaeuft(false);
        return;
      }
      weiterNachLogin(router, weiter, r.nutzer);
    } catch (err) {
      setFehler(err.message);
      setLaeuft(false);
    }
  }

  async function linkAnfordern(e) {
    e.preventDefault();
    setLaeuft(true);
    setFehler("");
    try {
      await senden("/api/auth/magic-link", { body: { email } });
      setModus("link-gesendet");
    } catch (err) {
      setFehler(err.message);
    } finally {
      setLaeuft(false);
    }
  }

  const registrieren = `/registrieren${weiter ? `?weiter=${encodeURIComponent(weiter)}` : ""}`;

  if (modus === "zwei-faktor") {
    return (
      <ZweiFaktorSchritt
        onErfolg={(r) => weiterNachLogin(router, weiter, r.nutzer)}
        onAbbrechen={(text) => {
          setModus("passwort");
          setPasswort("");
          setMeldung(text ? { ton: "fehler", text } : null);
        }}
      />
    );
  }

  if (modus === "link-gesendet") {
    return (
      <div role="status" className="rounded-2xl bg-ov-50 p-6 ring-1 ring-ov-200">
        <MailCheck aria-hidden="true" className="h-8 w-8 text-ov-600" />
        <p className="mt-3 font-display text-[19px] font-bold text-ink-900">Bitte prüfen Sie Ihr Postfach</p>
        <p className="mt-1.5 text-[14.5px] leading-relaxed text-ink-700">
          Wenn ein Konto mit {email || "dieser Adresse"} besteht, haben wir Ihnen einen Anmelde-Link gesendet. Er ist 15 Minuten gültig und funktioniert nur einmal.
        </p>
        {demo && <p className="mt-3 text-[13px] text-ink-600">Demo-Modus: Es wird keine E-Mail versendet. Der Link steht im Server-Log und im Backoffice unter „E-Mail-Postausgang“.</p>}
        <button type="button" onClick={() => setModus("passwort")} className="mt-4 text-[14px] font-semibold text-ov-700 hover:text-ov-800">Zurück zur Anmeldung mit Passwort</button>
      </div>
    );
  }

  const tab = (m, label, Icon) => (
    <button
      type="button"
      role="tab"
      aria-selected={modus === m}
      aria-controls={`${id}-panel`}
      onClick={() => {
        setModus(m);
        setFehler("");
      }}
      className={cn("flex h-10 flex-1 items-center justify-center gap-2 rounded-full text-[14px] font-semibold transition-colors", modus === m ? "bg-white text-ink-900 shadow-sm ring-1 ring-ink-200" : "text-ink-600 hover:text-ink-900")}
    >
      <Icon aria-hidden="true" className="h-4 w-4" /> {label}
    </button>
  );

  return (
    <div className="space-y-6">
      {meldung && (meldung.ton === "ok" ? <ErfolgBox>{meldung.text}</ErfolgBox> : <FehlerBox>{meldung.text}</FehlerBox>)}
      <div role="tablist" aria-label="Anmeldeweg" className="flex gap-1 rounded-full bg-sand-100 p-1">
        {tab("passwort", "Passwort", KeyRound)}
        {tab("link", "E-Mail-Link", Wand2)}
      </div>
      <div id={`${id}-panel`} role="tabpanel">
        {modus === "passwort" ? (
          <form onSubmit={anmelden} className="space-y-4">
            <Feld id={`${id}-e`} label="E-Mail-Adresse">
              <input id={`${id}-e`} type="email" autoComplete="username" required value={email} onChange={(e) => setEmail(e.target.value)} className={eingabe} />
            </Feld>
            <Feld id={`${id}-p`} label="Passwort">
              <div className="relative">
                <input id={`${id}-p`} type={zeigen ? "text" : "password"} autoComplete="current-password" required value={passwort} onChange={(e) => setPasswort(e.target.value)} className={cn(eingabe, "pr-12")} />
                <button type="button" onClick={() => setZeigen((z) => !z)} className="absolute right-1.5 top-1.5 flex h-9 w-9 items-center justify-center rounded-lg text-ink-500 hover:bg-ink-100 hover:text-ink-800" aria-label={zeigen ? "Passwort verbergen" : "Passwort anzeigen"} aria-pressed={zeigen}>
                  {zeigen ? <EyeOff aria-hidden="true" className="h-4 w-4" /> : <Eye aria-hidden="true" className="h-4 w-4" />}
                </button>
              </div>
            </Feld>
            <div className="flex justify-end">
              <Link href="/passwort-vergessen" className="text-[13.5px] font-semibold text-ov-700 hover:text-ov-800">Passwort vergessen?</Link>
            </div>
            <FehlerBox>{fehler}</FehlerBox>
            <button type="submit" disabled={laeuft} className={knopf}>
              {laeuft ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : <LogIn aria-hidden="true" className="h-4 w-4" />}
              {laeuft ? "Anmeldung läuft …" : "Anmelden"}
            </button>
          </form>
        ) : (
          <form onSubmit={linkAnfordern} className="space-y-4">
            <p className="text-[14px] leading-relaxed text-ink-600">Ohne Passwort: Wir senden Ihnen einen einmaligen Anmelde-Link (15 Minuten gültig). Mit aktiver Zwei-Faktor-Anmeldung fragen wir danach zusätzlich Ihren Code ab.</p>
            <Feld id={`${id}-m`} label="E-Mail-Adresse">
              <input id={`${id}-m`} type="email" autoComplete="username" required value={email} onChange={(e) => setEmail(e.target.value)} className={eingabe} />
            </Feld>
            <FehlerBox>{fehler}</FehlerBox>
            <button type="submit" disabled={laeuft} className={knopf}>
              {laeuft ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : <Wand2 aria-hidden="true" className="h-4 w-4" />}
              Anmelde-Link senden
            </button>
          </form>
        )}
      </div>
      <p className="text-center text-[14.5px] text-ink-600">
        Noch kein Konto?{" "}
        <Link href={registrieren} className="font-semibold text-ov-700 hover:text-ov-800">Kostenlos registrieren</Link>
      </p>

      {demoKonten.length > 0 && (
        <div className="rounded-2xl bg-sun-300/20 p-4 ring-1 ring-inset ring-sun-400/40">
          <p className="text-[13px] font-semibold text-ink-900">Demo-Modus – fiktive Konten zum Ausprobieren</p>
          <p className="mt-0.5 text-[12.5px] text-ink-600">Passwort für alle: <code className="rounded bg-white px-1.5 py-0.5 text-[12px]">{demoKonten[0].passwort}</code></p>
          {["Kunden & Partner", "Energiegemeinschaft", "Backoffice"].filter((gruppe) => demoKonten.some((k) => (k.gruppe || "Kunden & Partner") === gruppe)).map((gruppe) => (
          <div key={gruppe} className="mt-3">
          <p className="text-[11.5px] font-semibold uppercase tracking-[0.12em] text-ink-500">{gruppe}</p>
          <div className="mt-1.5 flex flex-wrap gap-1.5">
            {demoKonten.filter((k) => (k.gruppe || "Kunden & Partner") === gruppe).map((k) => (
              <button
                key={k.email}
                type="button"
                onClick={() => {
                  setModus("passwort");
                  setEmail(k.email);
                  setPasswort(k.passwort);
                }}
                className="rounded-full bg-white px-3 py-1.5 text-[12.5px] font-semibold text-ink-700 ring-1 ring-inset ring-ink-200 hover:ring-ov-400"
              >
                {k.label}
              </button>
            ))}
          </div>
          </div>
          ))}
        </div>
      )}
    </div>
  );
}
"use client";

// Zweiter Schritt der Anmeldung: 6-stelliger Code aus der Authenticator-App oder Wiederherstellungscode,
// optional „Gerät 30 Tage merken“. Wird nach Passwort, E-Mail-Link und Passwort-Reset eingeblendet.

import { useId, useState } from "react";
import { KeyRound, Loader2, ShieldCheck } from "lucide-react";
import { senden } from "@/lib/plattform/client";
import { eingabe, Feld, FehlerBox } from "@/components/Portal/felder";
import { cn } from "@/components/ui/cn";

const knopf =
  "inline-flex h-12 w-full items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] transition-colors hover:bg-ov-700 disabled:opacity-60";

export default function ZweiFaktorSchritt({ onErfolg, onAbbrechen }) {
  const id = useId();
  const [code, setCode] = useState("");
  const [wiederherstellung, setWiederherstellung] = useState(false);
  const [merken, setMerken] = useState(false);
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");

  async function pruefen(e) {
    e.preventDefault();
    setLaeuft(true);
    setFehler("");
    try {
      const r = await senden("/api/auth/zwei-faktor", { body: { code, merken } });
      onErfolg?.(r);
    } catch (err) {
      setFehler(err.message);
      setCode("");
      setLaeuft(false);
      if (err.status === 401 && /abgelaufen/.test(err.message)) onAbbrechen?.(err.message);
    }
  }

  return (
    <form onSubmit={pruefen} className="space-y-5">
      <div className="flex items-start gap-3 rounded-2xl bg-ov-50 p-4 ring-1 ring-inset ring-ov-200">
        <ShieldCheck aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-ov-700" />
        <p className="text-[14px] leading-relaxed text-ov-900">
          {wiederherstellung
            ? "Geben Sie einen Ihrer Wiederherstellungscodes ein (Format XXXXX-XXXXX). Jeder Code funktioniert nur einmal."
            : "Ihr Konto ist mit einem zweiten Faktor geschützt. Geben Sie den aktuellen 6-stelligen Code aus Ihrer Authenticator-App ein."}
        </p>
      </div>
      <Feld id={`${id}-c`} label={wiederherstellung ? "Wiederherstellungscode" : "Code aus der App"}>
        <input
          id={`${id}-c`}
          key={wiederherstellung ? "w" : "t"}
          autoFocus
          required
          autoComplete="one-time-code"
          inputMode={wiederherstellung ? "text" : "numeric"}
          maxLength={wiederherstellung ? 11 : 6}
          value={code}
          onChange={(e) => setCode(wiederherstellung ? e.target.value.toUpperCase() : e.target.value.replace(/[^0-9]/g, ""))}
          className={cn(eingabe, "text-center font-mono text-[20px] tracking-[0.3em]", wiederherstellung && "text-[17px] tracking-[0.12em]")}
        />
      </Feld>
      <label className="flex cursor-pointer items-start gap-3 text-[14px] text-ink-700">
        <input type="checkbox" checked={merken} onChange={(e) => setMerken(e.target.checked)} className="mt-0.5 h-4 w-4 accent-[#558227]" />
        Dieses Gerät 30 Tage merken (nur auf eigenen, nicht geteilten Geräten)
      </label>
      <FehlerBox>{fehler}</FehlerBox>
      <button type="submit" disabled={laeuft || (!wiederherstellung && code.length !== 6) || (wiederherstellung && code.replace(/[^0-9A-Z]/g, "").length !== 10)} className={knopf}>
        {laeuft ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : <KeyRound aria-hidden="true" className="h-4 w-4" />}
        {laeuft ? "Wird geprüft …" : "Bestätigen & anmelden"}
      </button>
      <div className="flex flex-wrap items-center justify-between gap-2 text-[13.5px]">
        <button type="button" onClick={() => { setWiederherstellung((w) => !w); setCode(""); setFehler(""); }} className="font-semibold text-ov-700 hover:text-ov-800">
          {wiederherstellung ? "Code aus der App verwenden" : "Telefon nicht zur Hand? Wiederherstellungscode"}
        </button>
        {onAbbrechen && (
          <button type="button" onClick={() => onAbbrechen()} className="text-ink-500 hover:text-ink-800">
            Abbrechen
          </button>
        )}
      </div>
    </form>
  );
}
import { redirect } from "next/navigation";
import AuthRahmen from "@/components/Plattform/AuthRahmen";
import LoginFormular from "@/components/Plattform/LoginFormular";
import { abs } from "@/data/site";
import { aktuellerNutzer } from "@/lib/plattform/server/seite";
import { istDemo } from "@/lib/plattform/backend";
import { sicheresZiel } from "@/lib/plattform/client";
import { DEMO_KONTEN, DEMO_PASSWORT } from "@/lib/plattform/backend/demo/seed";
import { rolleLabel } from "@/lib/plattform/konstanten";

export const dynamic = "force-dynamic";

// Weitere Demo-Konten aus den Fach-Seeds (Energie, Entwicklung, Backoffice-Unterrollen)
const WEITERE_DEMO_KONTEN = [
  { email: "kommune@example.com", label: "Gemeinde", gruppe: "Kunden & Partner" },
  { email: "gutachter@example.com", label: "Gutachter/Planer", gruppe: "Kunden & Partner" },
  { email: "bank@example.com", label: "Bank (Leitung)", gruppe: "Kunden & Partner" },
  { email: "bank-sachbearbeitung@example.com", label: "Bank (Sachbearbeitung)", gruppe: "Kunden & Partner" },
  { email: "deal-investor1@example.com", label: "Zweiter Investor (Bieter)", gruppe: "Kunden & Partner" },
  { email: "lieferant@example.com", label: "Energieversorger", gruppe: "Kunden & Partner" },
  { email: "energie-kunde1@example.com", label: "Reststrom-Kunde", gruppe: "Kunden & Partner" },
  { email: "mitglied@example.com", label: "Mitglied (Sonnenland)", gruppe: "Energiegemeinschaft" },
  { email: "eg-obmann@example.com", label: "Obmann", gruppe: "Energiegemeinschaft" },
  { email: "eg-kassier@example.com", label: "Kassier", gruppe: "Energiegemeinschaft" },
  { email: "eg-pruefer@example.com", label: "Rechnungsprüfer", gruppe: "Energiegemeinschaft" },
  { email: "bo-akquise@example.com", label: "Akquise", gruppe: "Backoffice" },
  { email: "bo-projektleitung@example.com", label: "Projektleitung", gruppe: "Backoffice" },
  { email: "bo-transaktion@example.com", label: "Transaktion", gruppe: "Backoffice" },
  { email: "bo-compliance@example.com", label: "Compliance", gruppe: "Backoffice" },
  { email: "bo-compliance2@example.com", label: "Compliance (Vier-Augen)", gruppe: "Backoffice" },
  { email: "bo-buchhaltung@example.com", label: "Buchhaltung", gruppe: "Backoffice" },
  { email: "bo-betrieb@example.com", label: "Anlagenbetrieb", gruppe: "Backoffice" },
  { email: "bo-energie@example.com", label: "Energie", gruppe: "Backoffice" },
  { email: "bo-lesen@example.com", label: "Nur lesen", gruppe: "Backoffice" },
];

export const metadata = {
  title: "Anmelden | ÖkoInvest",
  description: "Anmeldung zum Portal von ÖkoInvest: Status Ihrer Anfragen, Flächen und Projekte, Projektbörse, Dokumente und Nachrichten an einem Ort.",
  alternates: { canonical: abs("/login") },
  robots: { index: false, follow: true },
};

export default async function Login({ searchParams }) {
  const sp = await searchParams;
  const weiter = typeof sp?.weiter === "string" ? sicheresZiel(sp.weiter, "") : "";
  const nutzer = await aktuellerNutzer().catch(() => null);
  if (nutzer) redirect(weiter || "/portal");

  const demoKonten = istDemo()
    ? [
        ...DEMO_KONTEN.map((k) => ({ email: k.email, label: rolleLabel(k.rollen[0]), gruppe: k.rollen[0] === "admin" ? "Backoffice" : "Kunden & Partner" })),
        ...WEITERE_DEMO_KONTEN,
      ].map((k) => ({ ...k, passwort: DEMO_PASSWORT() }))
    : [];

  return (
    <AuthRahmen eyebrow="Portal" titel="Willkommen zurück" text="Melden Sie sich an, um Status, Dokumente und Nachrichten zu Ihren Vorgängen zu sehen.">
      <LoginFormular weiter={weiter} hinweis={typeof sp?.hinweis === "string" ? sp.hinweis : ""} demoKonten={demoKonten} demo={istDemo()} />
    </AuthRahmen>
  );
}

"use client";

import { useId, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Check, Eye, EyeOff, Factory, FolderKanban, Landmark, LandPlot, Loader2, Tractor, TrendingUp, Users } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { senden, sicheresZiel } from "@/lib/plattform/client";
import { ROLLEN } from "@/lib/plattform/konstanten";
import { passwortFehler } from "@/lib/plattform/validierung";
import { eingabe, Feld, FehlerBox } from "@/components/Portal/felder";

const ICONS = { flaeche: LandPlot, landwirt: Tractor, investor: TrendingUp, anbieter: FolderKanban, unternehmen: Factory, mitglied: Users, kommune: Landmark };

function staerke(pw) {
  let s = 0;
  if (pw.length >= 10) s++;
  if (pw.length >= 14) s++;
  if (/[0-9]/.test(pw) && /[A-Za-zÄÖÜäöüß]/.test(pw)) s++;
  if (/[^A-Za-z0-9ÄÖÜäöüß]/.test(pw)) s++;
  return s;
}

export default function RegistrierFormular({ rolleStart, vorgang, weiter }) {
  const router = useRouter();
  const id = useId();
  const [rollen, setRollen] = useState(rolleStart ? [rolleStart] : []);
  const [f, setF] = useState({ vorname: "", nachname: "", firma: "", email: "", telefon: "", passwort: "", agb: false, website: "" });
  const [zeigen, setZeigen] = useState(false);
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const setze = (k, v) => setF((x) => ({ ...x, [k]: v }));
  const umschalten = (r) => setRollen((x) => (x.includes(r) ? x.filter((y) => y !== r) : [...x, r]));
  const pwHinweis = f.passwort ? passwortFehler(f.passwort) : "";
  const st = staerke(f.passwort);

  async function absenden(e) {
    e.preventDefault();
    setFehler("");
    if (!rollen.length) return setFehler("Bitte wählen Sie mindestens eine Rolle.");
    if (pwHinweis) return setFehler(pwHinweis);
    setLaeuft(true);
    try {
      await senden("/api/auth/registrieren", { body: { ...f, rollen, vorgang: vorgang || undefined } });
      router.replace(sicheresZiel(weiter, "/portal/willkommen")); // geführter Einstieg (Bedienung & Onboarding)
      router.refresh();
    } catch (err) {
      setFehler(err.message);
      setLaeuft(false);
    }
  }

  return (
    <form onSubmit={absenden} className="space-y-8">
      <fieldset>
        <legend className="font-display text-[17px] font-bold text-ink-900">1. Wofür möchten Sie das Portal nutzen?</legend>
        <p className="mt-1 text-[13.5px] text-ink-500">Mehrfachauswahl möglich – Rollen lassen sich später im Profil ergänzen.</p>
        <div className="mt-4 grid gap-3 sm:grid-cols-2">
          {ROLLEN.map((r) => {
            const Icon = ICONS[r.id];
            const aktiv = rollen.includes(r.id);
            return (
              <label
                key={r.id}
                className={cn(
                  "group relative flex cursor-pointer gap-3 rounded-2xl p-4 ring-1 ring-inset transition-all has-[:focus-visible]:ring-2 has-[:focus-visible]:ring-ov-500",
                  aktiv ? "bg-ov-50 ring-ov-400 shadow-[0_10px_30px_-18px_rgba(85,130,39,0.6)]" : "bg-white ring-ink-200 hover:ring-ink-300"
                )}
              >
                <input type="checkbox" checked={aktiv} onChange={() => umschalten(r.id)} className="sr-only" />
                <span className={cn("flex h-11 w-11 shrink-0 items-center justify-center rounded-xl transition-colors", aktiv ? "bg-ov-600 text-white" : "bg-sand-100 text-ov-700")}>
                  <Icon aria-hidden="true" className="h-5 w-5" />
                </span>
                <span className="min-w-0 pr-5">
                  <span className="block text-[15px] font-semibold text-ink-900">{r.label}</span>
                  <span className="mt-0.5 block text-[12.5px] leading-snug text-ink-500">{r.text}</span>
                </span>
                <span aria-hidden="true" className={cn("absolute right-3 top-3 flex h-5 w-5 items-center justify-center rounded-full ring-1", aktiv ? "bg-ov-600 text-white ring-ov-600" : "ring-ink-300")}>
                  {aktiv && <Check className="h-3 w-3" strokeWidth={3} />}
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>

      <fieldset className="space-y-4">
        <legend className="font-display text-[17px] font-bold text-ink-900">2. Ihre Angaben</legend>
        {vorgang && (
          <p className="rounded-xl bg-ov-50 px-4 py-3 text-[13.5px] text-ov-900 ring-1 ring-ov-200">
            Ihre Anfrage <span className="ov-num font-semibold">{vorgang}</span> wird mit dem Konto verknüpft, wenn Sie dieselbe E-Mail-Adresse verwenden.
          </p>
        )}
        <div className="grid gap-4 sm:grid-cols-2">
          <Feld id={`${id}-vn`} label="Vorname" pflicht>
            <input id={`${id}-vn`} required autoComplete="given-name" maxLength={80} className={eingabe} value={f.vorname} onChange={(e) => setze("vorname", e.target.value)} />
          </Feld>
          <Feld id={`${id}-nn`} label="Nachname" pflicht>
            <input id={`${id}-nn`} required autoComplete="family-name" maxLength={80} className={eingabe} value={f.nachname} onChange={(e) => setze("nachname", e.target.value)} />
          </Feld>
          <Feld id={`${id}-fi`} label="Unternehmen / Betrieb" className="sm:col-span-2">
            <input id={`${id}-fi`} autoComplete="organization" maxLength={120} className={eingabe} value={f.firma} onChange={(e) => setze("firma", e.target.value)} />
          </Feld>
          <Feld id={`${id}-em`} label="E-Mail-Adresse" pflicht>
            <input id={`${id}-em`} type="email" required autoComplete="email" maxLength={190} className={eingabe} value={f.email} onChange={(e) => setze("email", e.target.value)} />
          </Feld>
          <Feld id={`${id}-te`} label="Telefon">
            <input id={`${id}-te`} type="tel" autoComplete="tel" maxLength={40} className={eingabe} value={f.telefon} onChange={(e) => setze("telefon", e.target.value)} />
          </Feld>
          <Feld id={`${id}-pw`} label="Passwort" pflicht className="sm:col-span-2" hinweis={pwHinweis || "Mindestens 10 Zeichen, Buchstaben und eine Ziffer oder ein Sonderzeichen."}>
            <div className="relative">
              <input id={`${id}-pw`} type={zeigen ? "text" : "password"} required autoComplete="new-password" minLength={10} maxLength={200} aria-describedby={`${id}-pw-hinweis`} className={cn(eingabe, "pr-12")} value={f.passwort} onChange={(e) => setze("passwort", e.target.value)} />
              <button type="button" onClick={() => setZeigen((z) => !z)} className="absolute right-1.5 top-1.5 flex h-9 w-9 items-center justify-center rounded-lg text-ink-500 hover:bg-ink-100" aria-label={zeigen ? "Passwort verbergen" : "Passwort anzeigen"} aria-pressed={zeigen}>
                {zeigen ? <EyeOff aria-hidden="true" className="h-4 w-4" /> : <Eye aria-hidden="true" className="h-4 w-4" />}
              </button>
            </div>
            {f.passwort && (
              <div className="mt-2 flex gap-1" aria-hidden="true">
                {[0, 1, 2, 3].map((i) => (
                  <span key={i} className={cn("h-1.5 flex-1 rounded-full", i < st ? (st >= 3 ? "bg-ov-500" : "bg-sun-400") : "bg-ink-200")} />
                ))}
              </div>
            )}
          </Feld>
        </div>
      </fieldset>

      <input type="text" name="website" tabIndex={-1} autoComplete="off" aria-hidden="true" className="hidden" value={f.website} onChange={(e) => setze("website", e.target.value)} />

      <label className="flex items-start gap-3 text-[13.5px] leading-relaxed text-ink-600">
        <input type="checkbox" required checked={f.agb} onChange={(e) => setze("agb", e.target.checked)} className="mt-1 h-4 w-4 shrink-0 accent-[#558227]" />
        <span>
          Ich akzeptiere die <Link href="/nutzungsbedingungen" className="underline underline-offset-2">Nutzungsbedingungen</Link> und habe die{" "}
          <Link href="/datenschutz" className="underline underline-offset-2">Datenschutzerklärung</Link> gelesen. *
        </span>
      </label>

      <FehlerBox>{fehler}</FehlerBox>
      <button type="submit" disabled={laeuft} className="inline-flex h-12 w-full items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] transition-colors hover:bg-ov-700 disabled:opacity-60">
        {laeuft && <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" />}
        {laeuft ? "Konto wird angelegt …" : "Kostenloses Konto anlegen"}
      </button>
      <p className="text-center text-[14.5px] text-ink-600">
        Bereits registriert?{" "}
        <Link href={`/login${weiter ? `?weiter=${encodeURIComponent(weiter)}` : ""}`} className="font-semibold text-ov-700 hover:text-ov-800">Anmelden</Link>
      </p>
    </form>
  );
}
"use client";

import { useId, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Loader2, MailCheck } from "lucide-react";
import { senden } from "@/lib/plattform/client";
import { passwortFehler } from "@/lib/plattform/validierung";
import { eingabe, Feld, FehlerBox } from "@/components/Portal/felder";
import ZweiFaktorSchritt from "./ZweiFaktorSchritt";
import PasswortStaerke from "@/components/Portal/Sicherheit/PasswortStaerke";

const knopf =
  "inline-flex h-12 w-full items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white shadow-[0_8px_24px_-8px_rgba(102,153,51,0.65)] transition-colors hover:bg-ov-700 disabled:opacity-60";

/** Link anfordern */
export function PasswortAnfordern({ demo = false }) {
  const id = useId();
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("offen");
  const [fehler, setFehler] = useState("");

  async function absenden(e) {
    e.preventDefault();
    setStatus("sendet");
    setFehler("");
    try {
      await senden("/api/auth/passwort-vergessen", { body: { email } });
      setStatus("fertig");
    } catch (err) {
      setFehler(err.message);
      setStatus("offen");
    }
  }

  if (status === "fertig") {
    return (
      <div role="status" className="rounded-2xl bg-ov-50 p-6 ring-1 ring-ov-200">
        <MailCheck aria-hidden="true" className="h-8 w-8 text-ov-600" />
        <p className="mt-3 font-display text-[19px] font-bold text-ink-900">Bitte prüfen Sie Ihr Postfach</p>
        <p className="mt-1.5 text-[14.5px] leading-relaxed text-ink-700">
          Wenn ein Konto mit dieser Adresse besteht, haben wir Ihnen einen Link zum Zurücksetzen gesendet. Er ist eine Stunde gültig.
        </p>
        {demo && <p className="mt-3 text-[13px] text-ink-600">Demo-Modus: Es wird keine E-Mail versendet. Der Link steht im Server-Log und im Backoffice unter „Nutzer & Protokoll“.</p>}
        <Link href="/login" className="mt-4 inline-block text-[14px] font-semibold text-ov-700 hover:text-ov-800">Zurück zur Anmeldung</Link>
      </div>
    );
  }

  return (
    <form onSubmit={absenden} className="space-y-4">
      <Feld id={`${id}-e`} label="E-Mail-Adresse Ihres Kontos">
        <input id={`${id}-e`} type="email" required autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} className={eingabe} />
      </Feld>
      <FehlerBox>{fehler}</FehlerBox>
      <button type="submit" disabled={status === "sendet"} className={knopf}>
        {status === "sendet" && <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" />}
        Link zum Zurücksetzen senden
      </button>
      <p className="text-center text-[14.5px] text-ink-600">
        Doch wieder eingefallen? <Link href="/login" className="font-semibold text-ov-700 hover:text-ov-800">Anmelden</Link>
      </p>
    </form>
  );
}

/** Neues Passwort mit Token setzen */
export function PasswortSetzen({ token }) {
  const router = useRouter();
  const id = useId();
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");
  const [laeuft, setLaeuft] = useState(false);
  const [fehler, setFehler] = useState("");
  const [zweiFaktor, setZweiFaktor] = useState(false);

  async function absenden(e) {
    e.preventDefault();
    const f = passwortFehler(pw) || (pw !== pw2 ? "Die Passwörter stimmen nicht überein." : "");
    if (f) return setFehler(f);
    setLaeuft(true);
    setFehler("");
    try {
      const r = await senden("/api/auth/passwort-setzen", { body: { token, passwort: pw } });
      if (r.zweiFaktor) {
        setZweiFaktor(true); // Passwort ist gespeichert – Anmeldung erst nach dem zweiten Faktor
        return;
      }
      router.replace("/portal");
      router.refresh();
    } catch (err) {
      setFehler(err.message);
      setLaeuft(false);
    }
  }

  if (zweiFaktor) {
    return (
      <div className="space-y-4">
        <p role="status" className="rounded-xl bg-ov-50 px-4 py-3 text-[14px] text-ov-900 ring-1 ring-ov-200">Ihr neues Passwort ist gespeichert. Bitte bestätigen Sie die Anmeldung mit Ihrem zweiten Faktor.</p>
        <ZweiFaktorSchritt onErfolg={() => { router.replace("/portal"); router.refresh(); }} onAbbrechen={() => router.replace("/login?hinweis=passwort-gesetzt")} />
      </div>
    );
  }

  return (
    <form onSubmit={absenden} className="space-y-4">
      <Feld id={`${id}-1`} label="Neues Passwort" hinweis="Mindestens 10 Zeichen, Buchstaben und eine Ziffer oder ein Sonderzeichen.">
        <input id={`${id}-1`} type="password" required minLength={10} autoComplete="new-password" value={pw} onChange={(e) => setPw(e.target.value)} className={eingabe} />
        <PasswortStaerke passwort={pw} />
      </Feld>
      <Feld id={`${id}-2`} label="Passwort wiederholen">
        <input id={`${id}-2`} type="password" required minLength={10} autoComplete="new-password" value={pw2} onChange={(e) => setPw2(e.target.value)} className={eingabe} />
      </Feld>
      <FehlerBox>{fehler}</FehlerBox>
      <button type="submit" disabled={laeuft} className={knopf}>
        {laeuft && <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" />}
        Passwort speichern & anmelden
      </button>
    </form>
  );
}
"use client";

import { useId, useState } from "react";
import Link from "next/link";
import { ArrowRight, CheckCircle2, Loader2, LockKeyhole } from "lucide-react";
import { cn } from "@/components/ui/cn";
import { herkunft } from "@/lib/herkunft";

/**
 * Einheitliches Anfrageformular aller Zielgruppen.
 *
 * Schickt an POST /api/anfrage → Vorgang im Backoffice. Wer sich später
 * mit derselben E-Mail registriert, sieht den Vorgang samt Status im Portal.
 *
 * Props:
 *  typ        flaeche | agri | investor | projekt | reststrom | energiegemeinschaft | genossenschaft | kommune | carport | speicher | kontakt
 *  daten      fachliche Zusatzdaten (z. B. Ergebnis eines Rechners) – werden mitgeschickt
 *  felder     zusätzliche Kontaktfelder: firma, telefon, plz, ort, land, nachricht
 *  titel/text/button/erfolgText  Beschriftungen
 *  dunkel     für Navy-Flächen
 */
export default function AnfrageFormular({
  typ = "kontakt",
  daten = {},
  felder = ["telefon", "nachricht"],
  titel,
  text,
  button = "Anfrage senden",
  erfolgText = "Danke! Ihre Anfrage ist eingegangen. Wir melden uns in der Regel innerhalb von zwei Werktagen.",
  rolle,
  className,
  dunkel = false,
}) {
  const id = useId();
  const [status, setStatus] = useState("offen"); // offen | sendet | fertig | fehler
  const [fehler, setFehler] = useState("");
  const [ergebnis, setErgebnis] = useState(null);

  async function absenden(e) {
    e.preventDefault();
    if (status === "sendet") return; // Doppelabsendung verhindern
    const fd = new FormData(e.currentTarget);
    if (fd.get("website")) return; // Honeypot
    const kontakt = {};
    for (const k of ["anrede", "vorname", "nachname", "firma", "email", "telefon", "plz", "ort", "land"]) {
      const v = fd.get(k);
      if (v) kontakt[k] = String(v).trim();
    }
    const nachricht = fd.get("nachricht");
    setStatus("sendet");
    setFehler("");
    try {
      const res = await fetch("/api/anfrage", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          typ,
          kontakt,
          daten: { ...daten, ...(nachricht ? { nachricht: String(nachricht) } : {}) },
          einwilligung: fd.get("einwilligung") === "on",
          herkunft: safeHerkunft(),
        }),
      });
      const json = await res.json().catch(() => ({}));
      if (!res.ok || !json.ok) throw new Error(json.error || "Senden fehlgeschlagen");
      setErgebnis(json);
      setStatus("fertig");
    } catch (err) {
      setFehler(err.message || "Senden fehlgeschlagen. Bitte versuchen Sie es erneut.");
      setStatus("fehler");
    }
  }

  const feld = cn(
    "block h-12 w-full rounded-xl px-4 text-[15px] outline-none transition-shadow placeholder:text-ink-400 focus-visible:ring-2 focus-visible:ring-ov-500",
    dunkel ? "bg-white/[0.07] text-white ring-1 ring-white/15 placeholder:text-white/40" : "bg-white text-ink-900 ring-1 ring-ink-200"
  );
  const label = cn("mb-1.5 block text-[13.5px] font-semibold", dunkel ? "text-white/85" : "text-ink-700");

  if (status === "fertig") {
    const registrieren = `/registrieren?${new URLSearchParams({ rolle: rolle || rolleFuerTyp(typ), vorgang: ergebnis?.id || "" })}`;
    return (
      <div role="status" className={cn("rounded-3xl p-7 md:p-9", dunkel ? "bg-white/[0.06] ring-1 ring-white/10" : "bg-ov-50 ring-1 ring-ov-200", className)}>
        <CheckCircle2 aria-hidden="true" className="h-9 w-9 text-ov-500" />
        <p className={cn("mt-4 font-display text-[22px] font-bold", dunkel ? "text-white" : "text-ink-900")}>Anfrage eingegangen</p>
        <p className={cn("mt-2 text-[15.5px] leading-relaxed", dunkel ? "text-white/75" : "text-ink-700")}>{erfolgText}</p>
        {ergebnis?.id && (
          <p className={cn("mt-3 text-[13.5px]", dunkel ? "text-white/55" : "text-ink-500")}>
            Vorgangsnummer <span className="ov-num font-semibold">{ergebnis.id}</span>
          </p>
        )}
        <div className="mt-6 flex flex-col gap-3 sm:flex-row">
          <Link href={registrieren} className="inline-flex h-12 items-center justify-center gap-2 rounded-full bg-ov-600 px-6 text-[15px] font-semibold text-white hover:bg-ov-700">
            Status im Portal verfolgen <ArrowRight aria-hidden="true" className="h-4 w-4" />
          </Link>
        </div>
      </div>
    );
  }

  return (
    <form onSubmit={absenden} noValidate={false} className={cn("space-y-4", className)} aria-describedby={titel ? `${id}-t` : undefined}>
      {titel && (
        <div>
          <p id={`${id}-t`} className={cn("font-display text-[22px] font-bold", dunkel ? "text-white" : "text-ink-900")}>{titel}</p>
          {text && <p className={cn("mt-1.5 text-[15px] leading-relaxed", dunkel ? "text-white/70" : "text-ink-600")}>{text}</p>}
        </div>
      )}
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label htmlFor={`${id}-vn`} className={label}>Vorname *</label>
          <input id={`${id}-vn`} name="vorname" required autoComplete="given-name" className={feld} />
        </div>
        <div>
          <label htmlFor={`${id}-nn`} className={label}>Nachname *</label>
          <input id={`${id}-nn`} name="nachname" required autoComplete="family-name" className={feld} />
        </div>
        {felder.includes("firma") && (
          <div className="sm:col-span-2">
            <label htmlFor={`${id}-fi`} className={label}>Unternehmen / Betrieb</label>
            <input id={`${id}-fi`} name="firma" autoComplete="organization" className={feld} />
          </div>
        )}
        <div className={felder.includes("telefon") ? "" : "sm:col-span-2"}>
          <label htmlFor={`${id}-em`} className={label}>E-Mail *</label>
          <input id={`${id}-em`} name="email" type="email" required autoComplete="email" className={feld} />
        </div>
        {felder.includes("telefon") && (
          <div>
            <label htmlFor={`${id}-te`} className={label}>Telefon</label>
            <input id={`${id}-te`} name="telefon" type="tel" autoComplete="tel" className={feld} />
          </div>
        )}
        {felder.includes("plz") && (
          <div>
            <label htmlFor={`${id}-plz`} className={label}>PLZ</label>
            <input id={`${id}-plz`} name="plz" inputMode="numeric" autoComplete="postal-code" className={feld} />
          </div>
        )}
        {felder.includes("ort") && (
          <div>
            <label htmlFor={`${id}-ort`} className={label}>Ort</label>
            <input id={`${id}-ort`} name="ort" autoComplete="address-level2" className={feld} />
          </div>
        )}
        {felder.includes("land") && (
          <div className="sm:col-span-2">
            <label htmlFor={`${id}-la`} className={label}>Land</label>
            <select id={`${id}-la`} name="land" className={feld} defaultValue="DE">
              <option value="DE">Deutschland</option>
              <option value="AT">Österreich</option>
              <option value="CH">Schweiz</option>
            </select>
          </div>
        )}
        {felder.includes("nachricht") && (
          <div className="sm:col-span-2">
            <label htmlFor={`${id}-na`} className={label}>Ihre Nachricht</label>
            <textarea id={`${id}-na`} name="nachricht" rows={4} className={cn(feld, "h-auto py-3")} />
